screens.script:
const weights = [8,4,2,1];
let bits = [0,0,0,0];
let records = new Map();
let basisEstablished = false;
let advancedRecorded = false;
let transferCorrect = false;
const sum = () => bits.reduce((n,b,i) => n+b*weights[i],0);
const sameCountDifferentValue = () => {
  const all = [...records.values()];
  return all.some((a,i) => all.some((b,j) => i!==j && a.lit===b.lit && a.value!==b.value));
};
const basicNow = () => sameCountDifferentValue() && records.has('0101') && sum()===5 && root.querySelector('#explanation').value==='weight';
const render = () => {
  root.querySelector('#value').textContent = bits.join('')+' = '+sum();
  root.querySelectorAll('[data-bit]').forEach((b,i) => {
    b.textContent='💡 '+weights[i]+'：'+(bits[i]?'开':'关');
    b.setAttribute('aria-pressed',String(Boolean(bits[i])));
  });
};
root.querySelectorAll('[data-bit]').forEach((b,i) => b.addEventListener('click', () => {
  bits[i]=1-bits[i];render();
  api.feedback('切换权值 '+weights[i]+'，总数现在是 '+sum()+'。');api.changed();
}));
root.querySelector('#record').addEventListener('click', () => {
  if(root.querySelector('#prediction').value==='unknown') {api.feedback('先作一个预测，再记录实验。');return;}
  records.set(bits.join(''),{value:sum(),lit:bits.reduce((a,b)=>a+b,0)});
  if(basisEstablished && sum()===10) advancedRecorded=true;
  if(basicNow()) basisEstablished=true;
  root.querySelector('#records').textContent='已记录：'+[...records].map(([code,r])=>code+'='+r.value+'（亮'+r.lit+'盏）').join('；');
  api.changed();
});
root.querySelector('#explanation').addEventListener('change', () => {if(basicNow()) basisEstablished=true;api.changed();});
root.querySelector('#transferCheck').addEventListener('click', () => {
  const raw=root.querySelector('#transferAnswer').value.trim();
  const target=weights[0]+weights[3];
  transferCorrect=raw!=='' && Number(raw)===target && basisEstablished && advancedRecorded;
  root.querySelector('#transferResult').textContent=!basisEstablished||!advancedRecorded?'先完成基础比较，再组成并记录 10。':transferCorrect?'正确：8+1=9，位置的权值决定数值。':'这里亮的是权值 8 和 1，并不是数亮灯数量；请把两个权值相加，再验证。';
  api.changed();
});
render();
return {
  evaluate() {return {basic:basisEstablished,star:basisEstablished&&advancedRecorded,transfer:transferCorrect};},
  reset() {
    bits=[0,0,0,0];records=new Map();basisEstablished=false;advancedRecorded=false;transferCorrect=false;
    root.querySelector('#prediction').value='unknown';root.querySelector('#explanation').value='unknown';
    root.querySelector('#transferAnswer').value='';root.querySelector('#transferResult').textContent='';
    root.querySelector('#records').textContent='尚未比较';render();
  }
};

const w=[8,4,2,1];
let sw=[0,0,0,0];
let opened=new Set();
let basicDone=false;
let starDone=false;
let fixDone=false;
const total=()=>sw.reduce((acc,v,i)=>acc+v*w[i],0);
const checkBasic=()=>opened.has(6)&&root.querySelector('#parityRule').value==='last';
const paint=()=>{
  root.querySelector('#boxReadout').textContent='当前编码：'+sw.join('')+' ➔ '+total()+' 号格口';
  root.querySelectorAll('[data-sw]').forEach((btn,i)=>{
    btn.textContent='权值'+w[i]+'：'+sw[i];
    btn.setAttribute('aria-pressed',String(Boolean(sw[i])));
  });
};
root.querySelectorAll('[data-sw]').forEach((btn,i)=>btn.addEventListener('click',()=>{
  sw[i]=1-sw[i];paint();
  api.feedback('地址位 '+w[i]+' 切换为 '+sw[i]+'，指向 '+total()+' 号格口。');api.changed();
}));
root.querySelector('#lockBox').addEventListener('click',()=>{
  const num=total();
  opened.add(num);
  if(checkBasic()) basicDone=true;
  if(basicDone && opened.has(15)) starDone=true;
  root.querySelector('#unlockedList').textContent='已验证格口：'+[...opened].map(n=>n+'号').join('、');
  api.feedback('已验证 '+num+' 号格口（编码 '+sw.join('')+'）。');api.changed();
});
root.querySelector('#parityRule').addEventListener('change',()=>{
  if(checkBasic()) basicDone=true;
  if(basicDone && opened.has(15)) starDone=true;
  api.changed();
});
root.querySelector('#fixBtn').addEventListener('click',()=>{
  const val=Number(root.querySelector('#fixBox').value.trim());
  fixDone=basicDone&&starDone&&val===3;
  root.querySelector('#fixOut').textContent=!basicDone||!starDone?'请先完成 6 号格口基础验证与 15 号最大格口挑战。':fixDone?'排障成功：0011 = 2+1 = 3 号格口！':'再算算：编码 0011 点亮的是权值 2 和 1。';
  api.changed();
});
paint();
return {
  evaluate(){return {basic:basicDone,star:basicDone&&starDone,transfer:fixDone};},
  reset(){
    sw=[0,0,0,0];opened=new Set();basicDone=false;starDone=false;fixDone=false;
    root.querySelector('#parityRule').value='unknown';
    root.querySelector('#fixBox').value='';root.querySelector('#fixOut').textContent='';
    root.querySelector('#unlockedList').textContent='已验证格口：暂无';paint();
  }
};

let seenA=false,seenB=false,basicOk=false,starOk=false;
const refresh=()=>{
  basicOk=seenA&&seenB&&root.querySelector('#capSelect').value==='16';
  starOk=basicOk&&root.querySelector('#bit5Select').value==='32';
};
root.querySelector('#modeCount').addEventListener('click',()=>{
  seenA=true;
  root.querySelector('#modeCount').setAttribute('aria-pressed','true');
  root.querySelector('#modeSummary').textContent='方案A（只数盏数）：只能区分 0、1、2、3、4 盏亮灯，共 5 种状态（0001 与 1000 被当成同一种）。';
  refresh();api.feedback('已观察方案A：只数亮灯个数会丢失位置信息。');api.changed();
});
root.querySelector('#modeWeight').addEventListener('click',()=>{
  seenB=true;
  root.querySelector('#modeWeight').setAttribute('aria-pressed','true');
  root.querySelector('#modeSummary').textContent='方案B（位置权值）：从 0000（0）到 1111（15），每个编码数值唯一，共 2×2×2×2 = 16 种状态！';
  refresh();api.feedback('已观察方案B：位置权值让 4 盏灯拥有 16 种唯一状态。');api.changed();
});
root.querySelector('#capSelect').addEventListener('change',()=>{refresh();api.changed();});
root.querySelector('#bit5Select').addEventListener('change',()=>{refresh();api.changed();});
return {
  evaluate(){return {basic:basicOk,star:starOk,transfer:starOk};},
  reset(){
    seenA=false;seenB=false;basicOk=false;starOk=false;
    root.querySelector('#modeCount').setAttribute('aria-pressed','false');
    root.querySelector('#modeWeight').setAttribute('aria-pressed','false');
    root.querySelector('#modeSummary').textContent='请点击上方两个方案按钮对比容量差异';
    root.querySelector('#capSelect').value='unknown';
    root.querySelector('#bit5Select').value='unknown';
  }
};
